"""Stress plan solver: tight capacities, overlapping paths, wide benefit range."""
import json, random, sys
sys.path.insert(0,'/workspace/tmp')
from harness import run
from fuzz_plan import benefit_of, brute
from cmp_plan import equivalent

def make_case(rng):
    style = rng.randrange(4)
    if style == 0:      # few nodes, many flows, tiny caps
        nodes = ['n%d'%i for i in range(rng.randint(2,4))]
        caps = {n: rng.choice([0,1,1,2]) for n in nodes}
        nf = rng.randint(4, 12)
    elif style == 1:    # chain-ish
        nn = rng.randint(3,7)
        nodes = ['n%d'%i for i in range(nn)]
        caps = {n: rng.randint(1,3) for n in nodes}
        nf = rng.randint(4, 12)
    elif style == 2:    # two clusters
        nodes = ['a%d'%i for i in range(3)] + ['b%d'%i for i in range(3)]
        caps = {n: rng.choice([1,2,5]) for n in nodes}
        nf = rng.randint(4, 12)
    else:               # many equal benefits
        nodes = ['n%d'%i for i in range(rng.randint(2,5))]
        caps = {n: rng.choice([1,2]) for n in nodes}
        nf = rng.randint(4, 12)
    flows=[]
    for i in range(nf):
        k = rng.randint(2, min(5, len(nodes)))
        if rng.random()<0.6:
            pool = nodes if style!=2 else nodes[:3] if rng.random()<0.5 else nodes[3:]
            path=[]
            for _ in range(k):
                c=rng.choice(pool)
                if c not in path: path.append(c)
            while len(path)<2:
                c=rng.choice(nodes)
                if c not in path: path.append(c)
        else:
            path = rng.sample(nodes,k)
        H = rng.randint(8,12)
        while True:
            kinds=list('KDZQT')+[rng.choice('KDZ') for _ in range(H-5)]
            rng.shuffle(kinds)
            if kinds.count('K')>=1 and 4+kinds.count('D')<H: break
        flows.append({'id':'f%d'%i,'path':path,'template':bytes(rng.randrange(256) for _ in range(H)).hex(),'kinds':''.join(kinds)})
    offers={}
    for f in flows:
        H=len(f['template'])//2; kinds=f['kinds']; path=f['path']; runs=[]
        for _ in range(rng.randint(0,2)):
            hb=bytearray(rng.randrange(256) for _ in range(H))
            if rng.random()<0.8:
                for pos,c in enumerate(kinds):
                    if c=='K': hb[pos]=int(f['template'][2*pos:2*pos+2],16)
                    elif c=='Q': hb[pos]=rng.choice([0,7,8])
                    elif c=='T': hb[pos]=rng.choice([0,len(path)-1,len(path),len(path)+3,200])
            runs.append({'header':bytes(hb).hex(),'count':rng.choice([1,2,5,50,1000])})
        offers[f['id']]=runs
    pinned=[f['id'] for f in flows if rng.random()<0.15]
    return {'mode':'plan','capacities':caps,'flows':flows,'warmup':rng.choice([0,1,3,50,1001]),'pinned':pinned,'offers':offers}

def main():
    rng=random.Random(int(sys.argv[1])); n=int(sys.argv[2])
    reqs=[make_case(rng) for _ in range(n)]
    got=run(reqs)
    bad=0
    for req,g in zip(reqs,got):
        ben={f['id']:benefit_of(f,req['offers'][f['id']],req['warmup']) for f in req['flows']}
        exp=brute(req)
        msg=equivalent(req,g,exp,ben)
        if msg:
            bad+=1
            print('MISMATCH',msg)
            print(json.dumps(req))
            print('got',json.dumps(g,sort_keys=True),'exp',json.dumps(exp,sort_keys=True))
            open('/workspace/tmp/bad_case.json','w').write(json.dumps(req))
            if bad>2: break
    print('cases',n,'mismatches',bad)

if __name__=='__main__':
    main()
